def semver_sort(versions):
    def key(v):
        core, _, pre = v.partition('-')
        nums = tuple(int(x) for x in core.split('.'))
        if not pre:
            return (nums, (1,))
        parts = []
        for ident in pre.split('.'):
            parts.append((0, int(ident)) if ident.isdigit() else (1, ident))
        return (nums, (0, parts))
    return sorted(versions, key=key)

import re

def camel_to_snake(s):
    s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)
    s = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', s)
    return s.lower()

def min_remove_parens(s):
    chars = list(s)
    stack = []
    for i, ch in enumerate(chars):
        if ch == '(':
            stack.append(i)
        elif ch == ')':
            if stack:
                stack.pop()
            else:
                chars[i] = ''
    for i in stack:
        chars[i] = ''
    return ''.join(chars)

def format_phone(text):
    d = ''.join(c for c in text if c.isdigit())
    if len(d) == 11 and d[0] == '1':
        d = d[1:]
    if len(d) != 10:
        raise ValueError('bad phone number')
    return f'({d[:3]}) {d[3:6]}-{d[6:]}'

def collapse_ranges(nums):
    if not nums:
        return ''
    parts = []
    start = prev = nums[0]
    for n in nums[1:] + [None]:
        if n != prev + 1 if n is not None else True:
            parts.append(f'{start}-{prev}' if start != prev else str(start))
            start = n
        if n is not None:
            prev = n
    return ','.join(parts)

def shell_split(cmd):
    out, cur, quote = [], [], None
    for ch in cmd:
        if quote:
            if ch == quote:
                quote = None
            else:
                cur.append(ch)
        elif ch in '\'"':
            quote = ch
        elif ch == ' ':
            if cur:
                out.append(''.join(cur))
                cur = []
        else:
            cur.append(ch)
    if quote:
        raise ValueError('unmatched quote')
    if cur:
        out.append(''.join(cur))
    return out

from decimal import Decimal, ROUND_HALF_UP

def invoice_total(items):
    rates = {'food': 0, 'books': 5}
    total = Decimal('0')
    for name, cat, qty, price in items:
        rate = Decimal(rates.get(cat, 10)) / 100
        line = Decimal(str(qty)) * Decimal(str(price)) * (1 + rate)
        total += line.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return float(total)
